import openpyxl

in_path, out_path = sys.argv[1], sys.argv[2]

wb = openpyxl.load_workbook(in_path)


def is_data_ws(s):
    try:
        return s['A1'].value == 'Mtrl' and s['G1'].value == 'This is what I need:'
    except Exception:
        return False


ws = next((s for s in wb.worksheets if is_data_ws(s)), wb.active)

# Total area per material = sum of (width * height) across the data rows.
sums = {}
for r in range(2, ws.max_row + 1):
    mat = ws.cell(row=r, column=1).value  # A  Mtrl
    w = ws.cell(row=r, column=2).value    # B  Width
    h = ws.cell(row=r, column=3).value    # C  Height
    if mat is None:
        break
    if isinstance(w, (int, float)) and isinstance(h, (int, float)):
        sums[mat] = sums.get(mat, 0) + w * h

# Fill the totals in column H for the materials declared in column G.
# Answer range is H2:H4 (rows 2-4), matching materials in G2:G4.
for r in range(2, 5):
    mat = ws.cell(row=r, column=7).value  # G
    if mat is not None and mat in sums:
        ws.cell(row=r, column=8).value = sums[mat]  # H

